    new_str_0910 = "今日不再提示",
    new_str_0909 = "（1）本游戏是一款卡牌放置养成类游戏，适用于年满16周岁及以上的用户，建议未成年人在家长监护下使用游戏产品。\n（2）本游戏基于架空的武侠故事背景和幻想世界观，剧情简单且积极向上，有少量基于历史和现实事件的改编，但不会与现实生活相混淆。游戏故事围绕与友人和伙伴的冒险剧情展开，游戏玩法基于界面操作、收集养成、解锁剧情、竞技对抗来提升自我并获得游戏乐趣，同时游戏中有基于文字的陌生人社交系统。\n（3）游戏中有用户实名认证系统，认证为未成年人的用户将接受以下管理：\n游戏中部分玩法和道具需要付费。未满8周岁的用户不能付费；8周岁以上未满16周岁的未成年人用户，单次充值金额不得超过50元人民币，每月充值金额累计不得超过\n200元人民币；16周岁以上的未成年人用户，单次充值金额不得超过100元人民币，每月充值金额累计不得超过400元人民币。\n未成年人用户仅可在周五、周六、周日和法定节假日每日20时至21时登录游戏，其他时间不得进行游戏。\n（4）本游戏游戏氛围轻松愉快，以体验主角与伙伴们的羁绊与冒险为主，画面风格与音乐制作融入中国风。玩家之间可以交流配合，共同完成游戏目标，能够培养团队协作意识和逻辑思维能力，带来正面的游戏体验。",
